    (300864, 100101, 9496, 'Mẩu json mình hay dùng lại, để đây cho ai cần. (#21)', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["connection pool","statement timeout","backpressure"]'::jsonb, '["Mô hình luồng","TCP"]'::jsonb, 4, NULL, 1, '[]'::jsonb, 'DEVOPS', now() - INTERVAL '267 days', now() - INTERVAL '267 days'),
    (300865, 102386, 9228, 'Chép lại từ buổi review hôm nay: thiết kế API phân trang. Nếu bạn đang gặp cùng chuyện, hãy kiểm tra cấu hình trước khi nghi ngờ mã nguồn. (#1546)', 'Điểm mấu chốt là thứ tự: phải đo trước khi sửa, và đo ở đúng tầng đang nghi ngờ. Đo ở tầng dễ đo nhất thường cho ra một con số đúng nhưng không liên quan.', '["cache invalidation","TTL","cache stampede"]'::jsonb, '["Redis cơ bản"]'::jsonb, 4, NULL, 1, '[]'::jsonb, 'BACKEND', now() - INTERVAL '176 days', now() - INTERVAL '176 days'),
    (300866, 101223, 9239, 'Bản tóm tắt cho ai chưa gặp vấn đề này: dẫn dắt một đội bốn người. Kết luận hơi ngược đời: giải pháp đơn giản hơn lại chạy nhanh hơn giải pháp thông minh. (#383)', 'Cách tiếp cận này đánh đổi bộ nhớ lấy thời gian. Với dữ liệu nhỏ thì lỗ, với dữ liệu lớn thì lãi — nên con số ranh giới quan trọng hơn bản thân kỹ thuật.', '["cache invalidation","TTL","cache stampede"]'::jsonb, '["Redis cơ bản"]'::jsonb, 1, NULL, 1, '[]'::jsonb, 'BACKEND', now() - INTERVAL '335 days', now() - INTERVAL '335 days'),
