    (300944, 100223, 9280, 'Mẩu plaintext mình hay dùng lại, để đây cho ai cần. (#143)', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["index tổ hợp","selectivity","query plan"]'::jsonb, '["B-tree","SQL"]'::jsonb, 2, NULL, 1, '[]'::jsonb, 'BACKEND', now() - INTERVAL '261 days', now() - INTERVAL '261 days'),
    (300945, 101705, 9272, 'Ghi lại sau một tuần vật lộn: giảm hoá đơn cloud. Thứ làm mình mất nhiều thời gian nhất là tin vào log thay vì đo thật. (#865)', 'Cấu hình này đặt một trần cứng ở phía máy chủ. Nó không làm truy vấn nhanh hơn; nó chỉ bảo đảm một truy vấn hỏng không kéo theo cả hệ thống.', '["connection pool","statement timeout","backpressure"]'::jsonb, '["Mô hình luồng","TCP"]'::jsonb, 3, NULL, 1, '[]'::jsonb, 'DEVOPS', now() - INTERVAL '346 days', now() - INTERVAL '346 days'),
    (300946, 102119, 9482, 'Ghi lại sau một tuần vật lộn: giảm kích thước app. Mất 3 giờ để tìm ra nguyên nhân và 20 nghìn hàng để sửa — tỉ lệ quen thuộc. (#1279)', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["connection pool","statement timeout","backpressure"]'::jsonb, '["Mô hình luồng","TCP"]'::jsonb, 4, NULL, 1, '[]'::jsonb, 'DEVOPS', now() - INTERVAL '34 days', now() - INTERVAL '34 days'),
